import unicodedata


def slugify(s):
    s = s.lower()
    # Transliterate: decompose unicode and strip non-ASCII
    s = unicodedata.normalize('NFKD', s)
    s = s.encode('ascii', 'ignore').decode('ascii')
    # Replace any non-alphanumeric character with a dash
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        else:
            out.append('-')
    # Collapse consecutive dashes and strip leading/trailing dashes
    return '-'.join(''.join(out).split('-')).strip('-')

